"use strict";(Array.isArray(self.webpackChunkvision_documentation_site)?self.webpackChunkvision_documentation_site:self.webpackChunkvision_documentation_site=[]).push([[273],{8562(e){e.exports=JSON.parse('{"version":{"pluginId":"default","version":"current","label":"Next","banner":null,"badge":false,"noIndex":false,"className":"docs-version-current","isLast":true,"docsSidebars":{"docs":[{"type":"link","href":"/opencv-rust-docs/","label":"Introduction","docId":"intro","unlisted":false},{"type":"link","href":"/opencv-rust-docs/getting-started","label":"Getting started","docId":"getting-started","unlisted":false},{"type":"link","href":"/opencv-rust-docs/modules","label":"Modules and coverage","docId":"modules","unlisted":false}]},"docs":{"getting-started":{"id":"getting-started","title":"Getting started","description":"The workspace is under development and is not published as a package. Its current core exposes Size, which stores non-negative width and height and provides checked_area(). The method returns None if multiplication overflows. This is an independent contract and does not claim OpenCV API compatibility.","sidebar":"docs"},"intro":{"id":"intro","title":"Introduction","description":"This independent library is in early development. Its long-term goal is to implement computer vision functionality in Rust without a runtime dependency on the OpenCV C++ core. Compatibility with OpenCV is not yet established.","sidebar":"docs"},"modules":{"id":"modules","title":"Modules and coverage","description":"The current workspace contains the core types Size and MatrixU8 and initial slices of imgproc, geometry and flann. MatrixU8 is an initial owned two-dimensional byte matrix. Three positive-size cases with valid access were compared with OpenCV on recorded Windows and Linux builds; this limited evidence does not establish full API parity.","sidebar":"docs"}}}}')}}]);